// Independent coefficient-pair field arithmetic, linear Miller chain and linear field DLP reference.
use std::{collections::BTreeSet,fmt::Write as _,fs,io::Write};
type F=(i64,i64);type P=Option<(F,F)>;fn md(x:i64)->i64{x.rem_euclid(61)}fn addf(x:F,y:F)->F{(md(x.0+y.0),md(x.1+y.1))}fn nf(x:F)->F{(md(-x.0),md(-x.1))}fn subf(x:F,y:F)->F{addf(x,nf(y))}fn mf(x:F,y:F)->F{(md(x.0*y.0+59*x.1*y.1),md(x.0*y.1+x.1*y.0))}fn pow(mut x:F,mut n:i64)->F{let mut r=(1,0);while n>0{if n%2==1{r=mf(r,x)}x=mf(x,x);n/=2;}r}fn div(x:F,y:F)->F{assert_ne!(y,(0,0));mf(x,pow(y,3719))}fn enc(x:F)->i64{x.0+61*x.1}
fn neg(p:P)->P{p.map(|(x,y)|(x,nf(y)))}fn on(p:P,a:i64,b:i64)->bool{p.is_none_or(|(x,y)|mf(y,y)==addf(addf(mf(mf(x,x),x),mf((a,0),x)),(b,0)))}
fn plus(p:P,q:P,a:i64)->P{let((x,y),(u,v))=match(p,q){(None,q)=>return q,(p,None)=>return p,(Some(p),Some(q))=>(p,q)};if x==u&&addf(y,v)==(0,0){return None}let m=if x==u{div(addf(mf((3,0),mf(x,x)),(a,0)),mf((2,0),y))}else{div(subf(v,y),subf(u,x))};let z=subf(subf(mf(m,m),x),u);let c=subf(y,mf(m,x));Some((z,nf(addf(mf(m,z),c))))}
fn mul(p:P,n:i64,a:i64)->P{let mut r=None;for _ in 0..n{r=plus(r,p,a)}r}fn chi(p:P)->P{p.map(|(x,y)|(div(x,(59,0)),div(y,(0,59))))}
fn line(p:P,q:P,at:P)->Option<F>{let((x,y),(u,v),(xx,yy))=(p?,q?,at?);if x==u&&addf(y,v)==(0,0){let z=subf(xx,x);return(z!=(0,0)).then_some(z)}let den=if x==u{mf((2,0),y)}else{subf(u,x)};if den==(0,0){return None}let m=if x==u{div(addf(mf((3,0),mf(x,x)),(21,0)),den)}else{div(subf(v,y),den)};let num=subf(subf(yy,y),mf(m,subf(xx,x)));let vert=plus(p,q,21).map_or((1,0),|(z,_)|subf(xx,z));(num!=(0,0)&&vert!=(0,0)).then(||div(num,vert))}
fn miller(p:P,at:P)->Option<F>{p?;at?;let mut r=p;let mut f=(1,0);for _ in 1..31{f=mf(f,line(r,p,at)?);r=plus(r,p,21)}assert_eq!(r,None);Some(f)}fn pair(p:P,q:P)->Option<F>{if p.is_none()||q.is_none(){return Some((1,0))}Some(nf(div(miller(p,q)?,miller(q,p)?)))}fn shifted(p:P,q:P,s:P)->Option<F>{if p.is_none()||q.is_none(){return Some((1,0))}Some(mf(div(miller(p,plus(q,s,21))?,miller(p,s)?),div(miller(q,neg(s))?,miller(q,plus(p,neg(s),21))?)))}
fn group(g:P,a:i64,b:i64)->Vec<P>{let mut set=BTreeSet::new();let mut p=None;for _ in 0..31{assert!(set.insert(p));assert!(on(p,a,b));p=plus(p,g,a);}assert_eq!(p,None);set.into_iter().collect()}
fn point(p:P)->String{match p{None=>"-1 -1".to_string(),Some((x,y))=>format!("{} {}",enc(x),enc(y))}}
fn solve(g:F,value:F)->i64{assert_ne!(g,(1,0));assert_eq!(pow(g,31),(1,0));let mut p=(1,0);for n in 0..31{if p==value{return n}p=mf(p,g);}panic!("finite field log absent")}
type Poly=Vec<F>;fn trim(a:&mut Poly){while a.last()==Some(&(0,0)){a.pop();}}fn degree(a:&Poly)->i32{a.len()as i32-1}fn scale(mut a:Poly,b:F)->Poly{for x in &mut a{*x=mf(*x,b)}trim(&mut a);a}fn sub(mut a:Poly,b:&Poly)->Poly{a.resize(a.len().max(b.len()),(0,0));for(i,&x)in b.iter().enumerate(){a[i]=subf(a[i],x)}trim(&mut a);a}
fn bound(n:i32,cap:i32,peak:&mut i32)->Result<(),()>{if n>cap{return Err(())}*peak=(*peak).max(n);Ok(())}
fn product(a:&Poly,b:&Poly,cap:i32,weight:i32,peak:&mut i32)->Result<Poly,()>{if a.is_empty()||b.is_empty(){return Ok(vec![])}bound(degree(a)+degree(b)+weight,cap,peak)?;let mut c=vec![(0,0);a.len()+b.len()-1];for(i,&x)in a.iter().enumerate(){for(j,&y)in b.iter().enumerate(){c[i+j]=addf(c[i+j],mf(x,y))}}trim(&mut c);Ok(c)}
fn divide(mut a:Poly,b:&Poly,cap:i32,peak:&mut i32)->Result<(Poly,Poly),()>{assert!(!b.is_empty());let mut q=vec![(0,0);(degree(&a)-degree(b)+1).max(0)as usize];while !a.is_empty()&&degree(&a)>=degree(b){let k=(degree(&a)-degree(b))as usize;let v=div(*a.last().unwrap(),*b.last().unwrap());q[k]=addf(q[k],v);let mut mono=vec![(0,0);k+1];mono[k]=v;a=sub(a,&product(&mono,b,cap,0,peak)?);}trim(&mut q);Ok((q,a))}
fn certificate(a:&[F],b:&[F],z:F,cap:i32,peak:&mut i32)->Result<(Poly,Poly,Poly,Poly,Poly),()>{bound(3,cap,peak)?;let mut f=vec![(1,0)];let mut h=f.clone();for &x in a{f=product(&f,&vec![nf(x),(1,0)],cap,0,peak)?;}for &x in b{h=product(&h,&vec![z,nf(x)],cap,0,peak)?;}let(mut r0,mut r1)=(f.clone(),h.clone());let(mut u0,mut u1,mut v0,mut v1)=(vec![(1,0)],vec![],vec![],vec![(1,0)]);while !r1.is_empty(){let(q,r)=divide(r0,&r1,cap,peak)?;let u=sub(u0,&product(&q,&u1,cap,3,peak)?);let v=sub(v0,&product(&q,&v1,cap,3,peak)?);r0=r1;r1=r;u0=u1;u1=u;v0=v1;v1=v;}let k=div((1,0),*r0.last().unwrap());r0=scale(r0,k);u0=scale(u0,k);v0=scale(v0,k);let uf=product(&u0,&f,cap,0,peak)?;let vh=product(&v0,&h,cap,0,peak)?;assert!(sub(sub(uf,&scale(vh,(-1,0))),&r0).is_empty());assert!(divide(f.clone(),&r0,cap,peak)?.1.is_empty()&&divide(h.clone(),&r0,cap,peak)?.1.is_empty());Ok((f,h,r0,u0,v0))}
fn eval(a:&Poly,x:F)->F{a.iter().rev().fold((0,0),|z,&c|addf(mf(z,x),c))}fn poly(a:&Poly)->String{let mut z=a.len().to_string();for &x in a{write!(z,",{}",enc(x)).unwrap()}z}
fn analyze_gcd()->(String,String){let g=Some(((0,0),(10,0)));let s=chi(Some(((37,0),(14,0))));let src=group(g,21,39);let base:Vec<_>=src.iter().copied().filter(|q|q.is_some()&&q< &neg(*q)).take(3).collect();assert_eq!(base.len(),3);let mut out="F61GCD 61 59 31 3 9 31 4\nBASE".to_string();for &q in &base{write!(out," {}",point(q)).unwrap()}out.push('\n');let(mut certified,mut unknown,mut rows,mut maxpeak)=(0,0,0,0);for cap in 0..=8{for(qi,&q)in src.iter().enumerate(){let z=pair(q,s).unwrap();for sign in [-1,1]{for sign2 in [-1,1]{let a:Vec<_>=base.iter().map(|&x|pair(if sign==1{x}else{neg(x)},s).unwrap()).collect();let b:Vec<_>=base.iter().map(|&x|pair(if sign2==1{x}else{neg(x)},s).unwrap()).collect();let mut peak=0;write!(out,"CELL {} {} {} {} ",cap,qi,sign,sign2).unwrap();match certificate(&a,&b,z,cap,&mut peak){Ok((f,h,d,u,v))=>{let mut found=vec![];for i in 0..3{if eval(&d,a[i])==(0,0){for j in 0..3{if mf(a[i],b[j])==z{found.push((i,j));}}}}let mut reference=vec![];for i in 0..3{for j in 0..3{if plus(if sign==1{base[i]}else{neg(base[i])},if sign2==1{base[j]}else{neg(base[j])},21)==q{reference.push((i,j));}}}assert_eq!(found,reference);write!(out,"C {} {} {} {} {} {} {}",peak,poly(&f),poly(&h),poly(&d),poly(&u),poly(&v),found.len()).unwrap();for(i,j)in &found{write!(out," {},{}",i,j).unwrap()}out.push('\n');certified+=1;rows+=found.len();maxpeak=maxpeak.max(peak);},Err(())=>{writeln!(out,"U {}",peak).unwrap();unknown+=1;}}}}}}writeln!(out,"CHECK {} {} {} {}\nMATRIX NA",certified,unknown,rows,maxpeak).unwrap();let receipt=format!("{{\"policy_count\":1,\"source_points\":31,\"caps\":9,\"sign_branches\":4,\"branch_rungs\":1116,\"certified\":{},\"unknown\":{},\"ordered_rows_across_caps\":{},\"expanded_field_witness_peak\":{},\"matrix_degree\":null,\"signed_verdict\":false}}\n",certified,unknown,rows,maxpeak);(out,receipt)}
fn main(){let a:Vec<_>=std::env::args().collect();if a.len()!=3{std::process::exit(2)}let r=std::panic::catch_unwind(||{let(expected,receipt)=analyze_gcd();let raw=fs::read_to_string(&a[1]).unwrap();assert!(raw==expected,"bounded field gcd certificate/point-row replay differs");fs::OpenOptions::new().write(true).create_new(true).open(&a[2]).unwrap().write_all(receipt.as_bytes()).unwrap();});if r.is_err(){std::process::exit(101)}}
